graphql.query:
query getMasterOptionTag ($master_option_tag_id: Int, $limit: Int, $offset: Int) {
    getMasterOptionTag (master_option_tag_id: $master_option_tag_id, limit: $limit, offset: $offset) {
        masterOptionTag {
            master_option_tag_id
            master_option_tag_name
        }
        totalMasterOptionTag
        currentCount
    }
}

query getOptionGroup ($prod_add_opt_group_id: Int,$use_for: String, $limit: Int, $offset: Int) {
    getOptionGroup (prod_add_opt_group_id: $prod_add_opt_group_id,use_for: $use_for, limit: $limit, offset: $offset) {
        optionGroup {
            prod_add_opt_group_id
            opt_group_name
            use_for
            display_style
            option_count
            is_collapse
            sort_order
        }
        totalOptionGroup
        currentCount
    }
}

query getCustomFormula ($formula_id: Int, $limit: Int, $offset: Int) {
    getCustomFormula (formula_id: $formula_id, limit: $limit, offset: $offset) {
        customFormula {
            formula_id
            formula_label
            formula_syntax
        }
        totalCustomFormula
        currentCount
    }
}

query getMasterOptionRange ($range_id: Int, $option_id: Int, $limit: Int, $offset: Int) {
    getMasterOptionRange (range_id: $range_id, option_id: $option_id, limit: $limit, offset: $offset) {
        masterOptionRange {
            range_id
            option_id
            from_range
            to_range
        }
        totalMasterOptionRange
        currentCount
    }
}

query productOptionsPrice ($attr_id: Int, $limit: Int, $offset: Int) {
    productOptionsPrice (attr_id: $attr_id, limit: $limit, offset: $offset) {
        productOptionsPrice {
            attr_id
            range_id
            price
            vendor_price
            from_range
            to_range
            site_admin_markup
        }
        totalProductOptionPrice
        currentCount
    }
}

query productOptionRules ($rule_id: Int, $limit: Int, $offset: Int) {
    productOptionRules (rule_id: $rule_id, limit: $limit, offset: $offset) {
        productOptionRules {
            rule_id
            rule_name
            rule_type
            source_option_ids
            source_attribute_ids
            hide_option_ids
            hide_option_attribute_ids
            status
            sort_order
            comparison_value
            disabled_for_admin
        }
        totalProductOptionRules
        currentCount
    }
}

query productPrice ($product_uuid: String, $limit: Int, $offset: Int) {
    productPrice (product_uuid: $product_uuid, limit: $limit, offset: $offset) {
        productPrice {
            size_id
            price
            vendor_price
            qty_from
            qty_to
            products_id
            user_type_id
            corporate_id
        }
        totalProductPrice
        currentCount
    }
}

query productsAttributePrice($attribute_id: Int, $size_id: Int, $limit: Int, $offset: Int) {
    productsAttributePrice(attribute_id: $attribute_id, size_id: $size_id, limit: $limit, offset: $offset) {
        productsAttributePrice {
            attribute_price_id
            attribute_id
            size_id
            quantity
            quantity_to
            attributes_price
            extra_page_price
        }
        totalProductsAttributePrice
        currentCount
    }
}

query products_attribute_price($attribute_id: Int, $size_id: Int, $limit: Int, $offset: Int) {
    products_attribute_price(attribute_id: $attribute_id, size_id: $size_id, limit: $limit, offset: $offset) {
        products_attribute_price {
            attribute_price_id
            attribute_id
            size_id
            quantity
            quantity_to
            attributes_price
            extra_page_price
        }
        total_products_attribute_price
        currentCount
    }
}

query productsImageGallery ($products_image_gallery_id: Int, $products_id: Int, $corporate_id: Int, $limit: Int, $offset: Int) {
    productsImageGallery ( products_image_gallery_id: $products_image_gallery_id, products_id: $products_id,corporate_id: $corporate_id, limit: $limit, offset: $offset) {
        productsImageGallery {
            products_image_gallery_id
            products_id
            corporate_id
            title
            products_thumb_image_name
            products_large_image_name
            option_id
            attribute_id
            option_ids
            attribute_ids
            sort_order
            status
        }
        totalProductsImageGallery
        currentCount
    }
}

query getProductSkuMatrix ($products_id: Int!, $prod_add_opt_ids: String!) {
    getProductSkuMatrix ( products_id: $products_id,prod_add_opt_ids: $prod_add_opt_ids) {
        matrix {
            size_id
            prod_add_opt_ids
            attribute_ids
        }
        totalRecords
    }
}

query productStocks ($product_id: Int!, $limit: Int, $offset: Int) {
    productStocks (product_id: $product_id, limit: $limit, offset: $offset) {
        productStocks {
            stock_id
            product_id
            product_name
            size_id
            size_title
			credit_stock
			debited_stock
            stock_quantity
            option_details
        }
        totalProductStocks
        currentCount
    }
}

query productStocks ($product_id: Int!, $limit: Int, $offset: Int) {
    productStocks (product_id: $product_id, limit: $limit, offset: $offset) {
        productStocks {
            stock_id
            product_id
            product_name
            size_id
            size_title
			credit_stock
			debited_stock
            stock_quantity
            option_details
        }
        totalProductStocks
    }
}

